nav_css:
/* ts-ww:start — the "Winding Willow" menu item (class ts-ww-nav). Ryan 2026-11-20: first the hamburger menu, then "yes, tighten" so it shows on a PC too.
   Measured on staging40: seven items fit the header on one line from 1256 px when the space between items is 0.5em, which the ts-corp block already uses
   at 1120-1349 px; this block uses it from 1350 px as well. Below 1256 px (and in the footer, where seven never fit) the item is hidden, so those menus
   look exactly as before. The phone and tablet menu (921 px and narrower) always shows it. */
@media (max-width: 1255px) {
  #ast-hf-menu-1 > .ts-ww-nav {
    display: none;
  }
}
@media (min-width: 1350px) {
  #ast-hf-menu-1 > .menu-item > .menu-link {
    padding-left: 0.5em;
    padding-right: 0.5em;
  }
}
#astra-footer-menu > .ts-ww-nav {
  display: none;
}
/* ts-ww:end */
